class Solution:
    def canSeePersonsCount(self, heights: List[int]) -> List[int]:
        ans=[]
        stack=[]
        n=len(heights)
        for i in range(n-1,-1,-1):
            if len(stack)==0:
                ans.append(0)
                stack.append(heights[i])
            else:
                if heights[i]<stack[-1]:
                    ans.append(1)
                    stack.append(heights[i])
                else:
                    ctr=0
                    while(len(stack)>0 and stack[-1]<heights[i]):
                        ctr+=1
                        stack.pop()
                    if len(stack)==0:
                        ans.append(ctr)
                    else:
                        ans.append(ctr+1)
                    stack.append(heights[i])
        return ans[::-1]

class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, r: int) -> str:
        n_letters = len([c for c in s if c == letter])
        stack = []

        for i, c in enumerate(s):
            while stack and stack[-1] > c and (len(s) - i + len(stack) > k) and (stack[-1] != letter or n_letters > r):
                d = stack.pop()
                if d == letter:
                    r += 1

            if len(stack) < k:
                if c == letter:
                    stack.append(c)
                    r -= 1
                elif k - len(stack) > r:
                    stack.append(c)

            if c == letter:
                n_letters -= 1

        return ''.join(stack)

